<?php require_once __DIR__.'/../config/bootstrap.php'; Auth::requireLogin(); $r=new Report($pdo); $customers=$pdo->query("SELECT id,name FROM customers WHERE status='active' ORDER BY name")->fetchAll(); $rows=$r->transactions($_GET); if(isset($_GET['export'])&&$_GET['export']==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment;filename=transactions.csv');$out=fopen('php://output','w');fputcsv($out,['Reference','Customer','Type','Amount','Currency','Status','Created']);foreach($rows as $x)fputcsv($out,[$x['transaction_reference'],$x['customer_name'],$x['transaction_type'],$x['amount'],$x['currency'],$x['status'],$x['created_at']]);fclose($out);exit;} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports · LedgerFlow</title><link rel="stylesheet" href="assets/app.css"></head><body><aside class="sidebar"><div class="brand">Ledger<span>Flow</span></div><nav><a href="index.php">Dashboard</a><a href="transactions.php">Transactions</a><a href="customers.php">Customers</a><a href="funding_sources.php">Funding Sources</a><a class="active" href="reports.php">Reports</a><a href="api_docs.php">API Docs</a></nav><div class="side-bottom"><span><?=e(Auth::user()['name'])?></span><a href="logout.php">Sign out</a></div></aside><main class="main"><header><div><p class="eyebrow">REPORTING</p><h1>Transaction report</h1><p class="muted">Filter activity and export a CSV for finance teams.</p></div><a class="btn primary" href="?<?=http_build_query(array_merge($_GET,['export'=>'csv']))?>">Export CSV</a></header><section class="panel"><form class="inline-form"><select name="customer_id"><option value="">All customers</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=((string)($_GET['customer_id']??''))===(string)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><input type="date" name="from" value="<?=e($_GET['from']??'')?>"><input type="date" name="to" value="<?=e($_GET['to']??'')?>"><select name="type"><option value="">All types</option><option value="payment" <?=($_GET['type']??'')==='payment'?'selected':''?>>payment</option><option value="deposit" <?=($_GET['type']??'')==='deposit'?'selected':''?>>deposit</option><option value="expense" <?=($_GET['type']??'')==='expense'?'selected':''?>>expense</option><option value="refund" <?=($_GET['type']??'')==='refund'?'selected':''?>>refund</option></select><button class="btn">Apply</button></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Type</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?=e($x['transaction_reference'])?></td><td><?=e($x['customer_name']??'—')?></td><td><?=e($x['transaction_type'])?></td><td><?=money($x['amount'],$x['currency'])?></td><td><span class="badge <?=e($x['status'])?>"><?=e($x['status'])?></span></td><td><?=e($x['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
